/* JAH demo program — JAH-NAPPS-000014 */
/* Pocket Packager */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Pocket Packager: run-length compression");
var s="";for(var i=0;i<14;i++)s+="AB";s+="XYZ";for(var j=0;j<9;j++)s+="Q";
var out="",k=0;
while(k<s.length){var c=s[k],n=1;while(s[k+n]===c)n++;out+=c+n;k+=n;}
console.log("raw bytes: "+s.length);
console.log("encoded bytes: "+out.length);
console.log("ratio: "+(out.length/s.length).toFixed(3));

